public IList<IList<int>> Permute(int[] nums)
{
    var result = new List<IList<int>>();
    Dfs(nums, 0, result);
    return result;
}

private void Dfs(int[] nums, int d, List<IList<int>> result)
{
    if (d == nums.Length) { result.Add(new List<int>(nums)); return; }
    for (int i = d; i < nums.Length; i++)
    {
        (nums[d], nums[i]) = (nums[i], nums[d]); // place nums[i] at depth d
        Dfs(nums, d + 1, result);                 // build the rest
        (nums[d], nums[i]) = (nums[i], nums[d]); // undo the swap (backtrack)
    }
}

public IList<IList<int>> Permute(int[] nums)
{
    var result = new List<IList<int>>();
    var current = new List<int>();
    var used = new bool[nums.Length];

    void Dfs()
    {
        if (current.Count == nums.Length) { result.Add(new List<int>(current)); return; }
        for (int i = 0; i < nums.Length; i++)
        {
            if (used[i]) continue;
            used[i] = true;                    // choose
            current.Add(nums[i]);
            Dfs();
            current.RemoveAt(current.Count - 1); // un-choose
            used[i] = false;                    // backtrack
        }
    }

    Dfs();
    return result;
}
